const policies=[{id:'F05/Q-74m-5',historical:'T22/71:307 și 74n:96. O linie este servită integral dintr-o singură gestiune; suma gestiunilor alimentează stocul transmis.',r1:'Metoda aloca a returnat ROȘU la 120 cerut cu 80+40 între două surse. Aceasta respectă decizia comportamentală documentată.',current:'Utilizarea mai multor G1 nu stabilește automat divizarea unei linii în două livrări. Dacă G3 transmite 120 fără explicație, auditează separat cazul unui client care comandă toate 120. Handoff A06-F07. O regulă de split generală ar fi modificare explicită a politicii, nu corecție obligatorie la metoda actuală.',state:'RECLASIFICAT_COMPORTAMENT_INTENȚIONAT_PENTRU_LINIE; NECONCORDANȚA AFIȘARE/ONORARE RĂMÂNE DE EXERSAT'},{id:'F07/D-05a-3',historical:'T355/05a:13 confirmă inițial locatorul L ca destinație a componentelor. Codul și testul produc o singură destinație.',current:'Cerința utilizatorului cere mutarea în locatorii noi înainte de pick. Nota poate fi păstrată urmată de amplasare confirmată spre L1/L2/L3. Gradul de acoperire se decide pe acest traseu. Nu se cere redesign dacă transferul existent acoperă cazul.',state:'REGULA NOTEI INTENȚIONATĂ; OBLIGAȚIE DE AMPLASARE ÎNAINTE DE PICK'},{id:'F06',historical:'T331 declară o pereche per gestiune contabilă. Indecșii reali ai fiecărui client confirmă topologia 1:1.',current:'G1.1/G1.2 și G2.1/G2.2 sunt dovedite prin două perechi. Cerința de N G2 la exact o singură G1 nu este expresă și se tratează separat de împărțirea pe locatori și drepturi.',state:'LIMITĂ CONFIRMATĂ; NEVOIA DE M:N NU SE INFERĂ'}];fs.writeFileSync(p.join(o,'corelari-si-politici.json'),JSON.stringify({policies,related_reports:out},null,2)+'\n');
